WITH churned_customers AS (
    SELECT customer_id
    FROM support_tickets
    GROUP BY customer_id
    HAVING MAX(created_at) < CURRENT_DATE - INTERVAL '180 days'
)
SELECT customer_id FROM churned_customers;

DELETE FROM support_tickets
WHERE customer_id IN (SELECT customer_id FROM churned_customers)
  AND created_at < CURRENT_DATE - INTERVAL '180 days';

